import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.a6FUKr6c.js";const u=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ui.md","filePath":"guide/ui.md","lastUpdated":1794504758000}'),s={name:"guide/ui.md"};function d(i,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p><code>@chamvi/ui</code> is a dashboard for the agents of an app: see what each agent does, start a run, watch runs live, answer approvals, look into agent state and see when cron subscriptions fire next. It is a prebuilt Vue 3 app (vuecs, the Glacier design) that your own <code>@chamvi/http</code> app serves on the same origin, so there is no CORS and no second deployment.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#DCE9F2;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/ui</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><p><code>uiRoutes()</code> returns the extra routes for <code>createHttpApp({ routes })</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">return</span><span style="color:#DCE9F2;"> createHttpApp({</span></span>
<span class="line"><span style="color:#DCE9F2;">    engine,</span></span>
<span class="line"><span style="color:#DCE9F2;">    auth: [staticTokens({</span></span>
<span class="line"><span style="color:#DCE9F2;">        tokens: [{</span></span>
<span class="line"><span style="color:#DCE9F2;">            value: process.env.ADMIN_TOKEN</span><span style="color:#8FD0F2;">!</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            id: </span><span style="color:#E7C58C;">&#39;admin&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            permissions: </span><span style="color:#E7C58C;">&#39;*&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        }],</span></span>
<span class="line"><span style="color:#DCE9F2;">    })],</span></span>
<span class="line"><span style="color:#7F95A6;">    // the dashboard at /ui, signed in with a pasted bearer token</span></span>
<span class="line"><span style="color:#DCE9F2;">    routes: uiRoutes(),</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p>Open <code>/ui/</code> and paste a token; the dashboard opens on the agents overview. Nothing of the dashboard runs on the server but one static file route; every page talks to the API it already has, with the signed-in principal&#39;s bearer token.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Shows</th><th>Needs</th></tr></thead><tbody><tr><td>Agents</td><td>A card per agent: its channel chips (GitHub events, cron expressions, hook paths, http), running and waiting runs, the next cron fire, a 24 h activity strip, the last run, the budget and the state collections; a name filter; a notice listing the <a href="/guide/agent-folders">agent folders</a> that failed to load, with their messages. The landing page after sign-in.</td><td><code>chamvi_run_read</code></td></tr><tr><td>Agent</td><td>The agent&#39;s budget, state collections and channel chips, Start run (with an <code>http.on()</code> subscription: a JSON payload sent to <code>POST /agents/:name/runs</code> as you) and View all runs, and four tabs: Overview (runs, failures, waiting approvals and tokens, recent runs, its waiting approvals, its subscriptions with route, hook or next fire), Runs (filtered by status), State (key-value entries and collections, read-only) and Schedules.</td><td><code>chamvi_run_read</code>; <code>chamvi_agent_run</code> to start; <code>chamvi_state_read</code> for State; <code>chamvi_agent_read</code> for the runs and state of a <a href="/guide/http#private-agents">private agent</a></td></tr><tr><td>Runs</td><td>Every run, newest first (<code>GET /runs?sort=-createdAt</code>), filtered by agent and status in the address bar; running and waiting counts, failures and tokens of the last 24 h; tokens per run. Refreshes every 5 s.</td><td><code>chamvi_run_read</code></td></tr><tr><td>Run</td><td>Status, budgets (steps, tokens, time), the envelope (channel, subscription, address, payload) and the step timeline (llm, tool and wait steps, inputs and outputs collapsed). For a <a href="/guide/dispatch">dispatched</a> run, a &quot;dispatched from&quot; link to its parent; for a parent, its dispatched runs (agent, role, status, at most 100, refreshed as the run updates), the subtree token total, and a &quot;Waits for N dispatched runs&quot; callout while it waits on them. Listing dispatched runs needs <code>chamvi_run_read</code>; an agent-scoped principal sees a note instead. Live over the run&#39;s SSE stream, including the streamed text of the step in progress. A cancel button with a confirmation.</td><td><code>chamvi_run_read</code> or <code>chamvi_agent_run</code>; <code>chamvi_run_cancel</code> to cancel</td></tr><tr><td>Approvals</td><td>Each waiting run with the request&#39;s title and body, the tool, the channel it went out through, the expiry countdown and a reason field; a request with <a href="/guide/approvals#offering-options">options</a> shows them as radios (one) or checkboxes (several), each <code>detail</code> preformatted in a closed <code>Details</code> block (a diff colored by line), and Approve waits for a fitting selection; <a href="/guide/approvals#showing-files">files</a> of the request and of each option show as thumbnails with their filename (PNG, JPEG, GIF and WebP inline, a click opens them full size; any other type is a download); Approve or Deny (<code>POST /runs/:id/approve</code>). The sidebar shows the count.</td><td><code>chamvi_run_read</code> to list, <code>chamvi_agent_approve</code> to answer</td></tr><tr><td>Schedules</td><td>The cron subscriptions per agent with the next fire time in the subscription&#39;s time zone.</td><td><code>chamvi_run_read</code></td></tr><tr><td>Connections</td><td>The connections the app&#39;s modules expose (e.g. a <a href="/deployment/whatsapp#session-store">WhatsApp session</a>) with type and status; a connection&#39;s page shows its live status and Reset session behind a confirmation in the page. Configuring a connection happens on its <a href="#connection-pages">page</a>. Listed in the sidebar only when there is a connection you may read.</td><td><code>chamvi_connection_read</code>; <code>chamvi_connection_write</code> for the live view and reset</td></tr></tbody></table><p>Agent names link to the agent page from every other page. The 24 h figures come from the newest 100 runs (of the agent on its page, of the whole app on the overview and the runs page), since the API has no time filter: more runs than that in a day show <code>100+</code>. Only tools that need an approval are listed, because an agent may build its tool set per run.</p><p>A principal without the grant a page needs sees a notice naming it; the rest of the dashboard keeps working. An approval link from a channel&#39;s message needs read access to its run (<code>chamvi_run_read</code> or <code>chamvi_agent_run</code>) besides <code>chamvi_agent_approve</code>. Each grant is checked for the agent or connection in question, with the same <a href="/guide/permissions">permission bindings</a> the server evaluates, so a role restricted to one agent sees that agent&#39;s controls only; the server still decides every request.</p><h2 id="connection-pages" tabindex="-1">Connection pages <a class="header-anchor" href="#connection-pages" aria-label="Permalink to &quot;Connection pages&quot;">​</a></h2><p>Mail, calendar, GitHub, Discord and WhatsApp connections are configured on their own pages, one package each. Add the page&#39;s module next to the provider&#39;s module:</p><table tabindex="0"><thead><tr><th>Page</th><th>Module</th><th>Package</th></tr></thead><tbody><tr><td>Mail</td><td><code>toolMailUiModule()</code></td><td><code>@chamvi/tool-mail-ui/module</code></td></tr><tr><td>Calendar</td><td><code>toolCalendarUiModule()</code></td><td><code>@chamvi/tool-calendar-ui/module</code></td></tr><tr><td>GitHub</td><td><code>githubUiModule()</code></td><td><code>@chamvi/github-ui/module</code></td></tr><tr><td>Discord</td><td><code>chatDiscordUiModule()</code></td><td><code>@chamvi/chat-discord-ui/module</code></td></tr><tr><td>WhatsApp</td><td><code>chatWhatsappUiModule()</code></td><td><code>@chamvi/chat-whatsapp-ui/module</code></td></tr></tbody></table><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#DCE9F2;"> { toolMailModule } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/tool-mail/module&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#DCE9F2;"> { toolMailUiModule } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/tool-mail-ui/module&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#DCE9F2;"> { uiModule } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/ui/module&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> modules = [uiModule(), toolMailModule(), toolMailUiModule()];</span></span></code></pre></div><p>Each page is served at <code>&lt;uiBase&gt;/ext/&lt;slug&gt;</code> and gets a sidebar item, shown to a principal who may read a connection of its type or holds <code>chamvi_connection_create</code> for that type. A connection without a page is listed under Connections and cannot be edited. A dashboard not at the default <code>/ui</code> needs the same value on both sides: <code>uiModule({ basePath: &#39;/admin&#39; })</code> and <code>toolMailUiModule({ uiBase: &#39;/admin&#39; })</code>. The package pages sign in like the dashboard: <code>uiModule({ auth })</code> in code configures them too, and without <code>uiModule()</code> they read the environment (<code>CHAMVI_UI_AUTHUP_CLIENT_ID</code>, <code>AUTHUP_URL</code>, <code>CHAMVI_UI_AUTHUP_REALM_ID</code>).</p><p>A page shows one state per field:</p><table tabindex="0"><thead><tr><th>The field</th><th>The form</th></tr></thead><tbody><tr><td>Unset or stored</td><td>Editable</td></tr><tr><td>Set from env or a <code>_FILE</code> variable</td><td>Locked, naming the variable; env wins over a stored value</td></tr><tr><td>A stored secret</td><td>&quot;Set&quot;, with Replace and Clear; a value is never shown or returned by the API</td></tr></tbody></table><p>Saved values take effect at the next start; the page shows &quot;Saved. Restart the app to apply.&quot; until a process has loaded them. Saving a secret, or anything that creates a stored connection, needs <code>CHAMVI_ENCRYPTION_KEYS</code> and is refused with a message naming it otherwise. Clearing a required secret is allowed and leaves the connection <code>incomplete</code> (a <code>chamvi start --check</code> issue, not a failed start, unless an env field is set too).</p><p>The accounts column and the Connections overview show <code>not configured</code>, <code>incomplete</code> (with what is missing or why the last start refused it, such as a missing <code>CHAMVI_PUBLIC_URL</code>) or <code>configured</code>; a connection with nothing running in this process, as mail and calendar always are, reads <code>configured</code> and not <code>disconnected</code>. <strong>Test</strong> checks the saved values only, never what is typed in the form: mail logs in over IMAP and out again, calendar logs in over CalDAV, GitHub calls <code>GET /app</code> with the App JWT and Discord calls <code>GET /users/@me</code>, each within 30 seconds and answering a generic reason on failure. Changing a field that decides where a secret is sent (the mail host, port or security, the calendar URL, the GitHub API URL) needs every stored secret entered again, and is refused while one of them comes from the environment.</p><p>Editing and deleting need <code>chamvi_connection_write</code>, adding an account of a multi-account type (mail, calendar) <code>chamvi_connection_create</code> for the type. Deleting is offered for stored accounts only; an account declared in env or a module cannot be deleted.</p><div class="tip custom-block"><p class="custom-block-title">An account added here takes its secrets from the store alone</p><p>Env wins over a stored value field by field only for an account the environment declares (one listed in <code>CHAMVI_MAIL_ACCOUNTS</code> or <code>CHAMVI_CALENDAR_ACCOUNTS</code>). An account that exists only in the store never reads <code>CHAMVI_MAIL_&lt;ID&gt;_USER</code>, <code>CHAMVI_MAIL_&lt;ID&gt;_PASSWORD</code>, their <code>_FILE</code> forms or the calendar equivalents: a leftover <code>CHAMVI_MAIL_WORK_PASSWORD</code> is not the password of an account <code>work</code> someone adds here, and the start logs a warning naming each ignored variable. An account deleted and added again is tested with its stored values only. Whoever holds <code>chamvi_connection_create</code> still chooses where the secrets they enter are sent, so grant it deliberately and keep the app&#39;s outbound network limited (the chart&#39;s egress policy).</p></div><h2 id="sign-in" tabindex="-1">Sign-in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign-in&quot;">​</a></h2><ul><li><strong>Token</strong> (default): a static bearer token of <code>staticTokens()</code>. <code>GET /me</code> checks it before it is kept, in the tab&#39;s <code>sessionStorage</code> only; sign-out removes every <code>chamvi.</code> key but a pending approval link. Only a 401 drops a stored token: a reload while the API restarts or rate limits keeps it, and the next navigation tries again.</li><li><strong>authup</strong>: <code>auth.authup</code> adds &quot;Continue with authup&quot;, the OIDC code flow with PKCE through <code>@authup/client-web-kit</code>, whose tokens are kept in the tab&#39;s <code>sessionStorage</code> (<code>chamvi.authup.*</code>), never in cookies. The authup client needs <code>&lt;origin&gt;&lt;uiBase&gt;/login/callback</code> as a redirect URI. Pair it with the app&#39;s <code>authup()</code> authenticator. <code>auth.tokens: false</code> hides the token form (then <code>auth.authup</code> is required).</li></ul><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">return</span><span style="color:#DCE9F2;"> createHttpApp({</span></span>
<span class="line"><span style="color:#DCE9F2;">    engine,</span></span>
<span class="line"><span style="color:#DCE9F2;">    basePath: </span><span style="color:#E7C58C;">&#39;/api&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    auth: [authup(options)],</span></span>
<span class="line"><span style="color:#DCE9F2;">    routes: uiRoutes({</span></span>
<span class="line"><span style="color:#7F95A6;">        // served at /api/console/, the API under /api</span></span>
<span class="line"><span style="color:#DCE9F2;">        basePath: </span><span style="color:#E7C58C;">&#39;/console&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        auth: {</span></span>
<span class="line"><span style="color:#DCE9F2;">            tokens: </span><span style="color:#8FD0F2;">false</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#7F95A6;">            // the authup client needs &lt;origin&gt;/api/console/login/callback as a redirect URI</span></span>
<span class="line"><span style="color:#DCE9F2;">            authup: { url: </span><span style="color:#E7C58C;">&#39;https://auth.example.com/api&#39;</span><span style="color:#DCE9F2;">, clientId: </span><span style="color:#E7C58C;">&#39;chamvi&#39;</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">        },</span></span>
<span class="line"><span style="color:#DCE9F2;">    }),</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p>A revoked token or an expired authup session answers 401: the dashboard refreshes the authup session once, else signs out and returns to the sign-in page with the page it was on as the way back.</p><h2 id="approval-links" tabindex="-1">Approval links <a class="header-anchor" href="#approval-links" aria-label="Permalink to &quot;Approval links&quot;">​</a></h2><p>A channel&#39;s approval message (GitHub, OpenClaw, a channel you write) links a person straight to an approval by run, without a token: <code>&lt;origin&gt;&lt;uiBase&gt;/approvals?run=&lt;runId&gt;&amp;approval=&lt;approvalId&gt;</code> (<code>approval</code> is optional and then means the approval the run waits on when the page opens). A signed-out visit goes through sign-in, the token form or the authup round-trip, and comes back to the same URL. Signed in, the dashboard scrolls to that run&#39;s approval card, highlights and focuses it; Approve and Deny answer through <code>POST /runs/:id/approve</code> as the signed-in principal, so the link is only as powerful as the person who opens it. The page reads the run with <code>GET /runs/:id</code> (<code>chamvi_run_read</code> or <code>chamvi_agent_run</code>) and follows it with the inbox poll:</p><table tabindex="0"><thead><tr><th>The run</th><th>The page shows</th></tr></thead><tbody><tr><td>waits on that approval</td><td>the highlighted card</td></tr><tr><td>waits on another approval</td><td>a notice linking the run; the new approval is listed in the inbox</td></tr><tr><td>no longer waits (answered, finished) or the approval expired</td><td>a notice linking the run</td></tr><tr><td>waits, but the principal lacks <code>chamvi_agent_approve</code></td><td>a 403 notice naming the grant, and the card without Approve and Deny</td></tr><tr><td>is not readable with the principal&#39;s grants</td><td>a 403 notice</td></tr><tr><td>does not exist</td><td>&quot;not found&quot;</td></tr></tbody></table><p>Every answer goes through <code>POST /runs/:id/approve</code> by approval id, as the signed-in principal; a run that moved on to another approval answers 409.</p><h2 id="serving" tabindex="-1">Serving <a class="header-anchor" href="#serving" aria-label="Permalink to &quot;Serving&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>basePath</code></td><td><code>&#39;/ui&#39;</code></td><td>The dashboard&#39;s path under the app&#39;s <code>basePath</code>, lower case</td></tr><tr><td><code>auth.tokens</code></td><td><code>true</code></td><td>Offer the token form</td></tr><tr><td><code>auth.authup</code></td><td>none</td><td><code>{ url, clientId, realmId? }</code></td></tr><tr><td><code>root</code></td><td>the package&#39;s <code>dist/app</code></td><td>Another build folder</td></tr></tbody></table><ul><li>Every <code>GET</code> below <code>basePath</code> answers a file of the build, <code>index.html</code> for any other path without an extension (the client routes), or 404. Hashed files under <code>assets/</code> are cached for a year (<code>immutable</code>), the rest <code>no-cache</code>.</li><li><code>index.html</code> gets <code>&lt;base href=&quot;&lt;uiBase&gt;/&quot;&gt;</code> and the config (<code>apiBase</code>, <code>uiBase</code>, the sign-in modes) as a JSON block, so the same build works under any <code>basePath</code>.</li><li>Paths are decoded once and refused on <code>..</code>, <code>.</code>, empty segments, backslashes, NUL and double encoding: nothing outside the build is read.</li><li>Every answer carries a Content-Security-Policy (<code>default-src &#39;self&#39;</code>, scripts only from the build, <code>connect-src</code> and <code>form-action</code> add the authup origin, images also from <code>blob:</code> (approval files, read with the bearer token), <code>frame-ancestors &#39;none&#39;</code>), <code>x-content-type-options: nosniff</code>, <code>x-frame-options: DENY</code> and <code>referrer-policy: no-referrer</code>. Fonts and icons are part of the build; nothing loads from a CDN.</li><li>The route checks no credentials (the build holds no secret) and skips the rate limiter.</li></ul><p>Behind a proxy that mounts the app under a prefix, set the app&#39;s <code>basePath</code>; the dashboard and the <a href="#connection-pages">connection pages</a> follow it. Invalid options throw <code>InvalidAgentDefinitionError</code>; a missing build is reported on the first request (500 and <code>onError</code>), so the build may land later, e.g. in a container image.</p><h2 id="live-updates" tabindex="-1">Live updates <a class="header-anchor" href="#live-updates" aria-label="Permalink to &quot;Live updates&quot;">​</a></h2><p>The runs list and the inbox poll every 5 s. The run page follows <code>GET /runs/:id/stream</code> with a fetch-based reader (an <code>EventSource</code> cannot send the bearer header): after a dropped connection it reconnects with the last step index as <code>Last-Event-ID</code> (1, 2, 5, then every 10 s, or the <code>Retry-After</code> of a 503 from the stream cap), so a step is never lost or shown twice. Streamed text belongs to the model step in progress and gives way to the step once it is stored.</p>`,35)])])}const g=t(s,[["render",d]]);export{u as __pageData,g as default};
